import numpy as np

rng = np.random.default_rng(0)


def relu(x):
    return np.maximum(0, x)


class TwoLayerNet:
    """numpy version of: nn.Sequential(nn.Linear(in_f, hidden), nn.ReLU(), nn.Linear(hidden, out_f))"""

    def __init__(self, in_f, hidden, out_f):
        self.W1 = rng.standard_normal((in_f, hidden)) * 0.1
        self.b1 = np.zeros(hidden)
        self.W2 = rng.standard_normal((hidden, out_f)) * 0.1
        self.b2 = np.zeros(out_f)

    def forward(self, x):
        return relu(x @ self.W1 + self.b1) @ self.W2 + self.b2

    def __call__(self, x):
        return self.forward(x)

    def parameters(self):
        return [self.W1, self.b1, self.W2, self.b2]


net = TwoLayerNet(4, 8, 1)
x = rng.standard_normal((5, 4))   # a batch of 5 samples with 4 features
out = net(x)
print("Output shape:", None if out is None else out.shape)
